package java_practice;

public class PositiveNegative {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num=0;
		if(num==0)
		
			System.out.println("Zero");
			
		else if(num>0)
		
			System.out.println("Positive");
			
		
		else
		
			System.out.println("Negative");
		

	}

}
